import bpy,math,json
from bpy_extras.object_utils import world_to_camera_view
from mathutils import Vector
from pathlib import Path
out=Path('/workspace/scratch/girtas-NW-run-opposite-AIR-clear-backknee-guide-v07')
# FOOT tuples=(forwardY,ankleZ,contactkind). Both AIR poses have true clearance and fixed bone lengths.
phases=[{'phase':'AIR_LEFT_TRAILING_TO_RIGHT_LEADING_BOTH_CLEAR','hipZ':1.10,'left':(-.70,.90,'air_trailing'),'right':(.60,.30,'air_leading')}]
def mat(n,c):
 m=bpy.data.materials.new(n);m.diffuse_color=(*c,1);return m
def ball(n,p,s,m):
 bpy.ops.mesh.primitive_uv_sphere_add(segments=24,ring_count=12,location=p);o=bpy.context.object;o.name=n;o.scale=s;o.data.materials.append(m);return o
def limb(n,a,b,r,m):
 d=Vector(b)-Vector(a);mid=(Vector(a)+Vector(b))/2;bpy.ops.mesh.primitive_cylinder_add(vertices=24,radius=r,depth=d.length,location=mid);o=bpy.context.object;o.name=n;o.rotation_euler=d.to_track_quat('Z','Y').to_euler();o.data.materials.append(m)
def knee(hip,ankle):
 y0,z0=hip[1:];y1,z1=ankle[1:];dy=y1-y0;dz=z1-z0;dist=math.hypot(dy,dz);L=.57
 assert 0<dist<2*L,(hip,ankle,dist)
 h=math.sqrt(L*L-dist*dist/4)
 return (hip[0],(y0+y1)/2+h*(-dz/dist),(z0+z1)/2+h*(dy/dist))
proof=[]
for idx,phase in enumerate(phases):
 bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)
 gray=mat('bodyGray'+str(idx),(.46,.49,.54));near=mat('NEAR_LEFT_blue'+str(idx),(.04,.5,.9));far=mat('FAR_RIGHT_orange'+str(idx),(.95,.26,.06));black=mat('faceforwardindicator'+str(idx),(.10,.11,.13));bob=phase['hipZ']-1.07
 ball('pelvis',(0,0,1.07+bob),(.25,.15,.16),gray);ball('torso',(0,0,1.37+bob),(.32,.17,.32),gray);limb('neck',(0,0,1.58+bob),(0,0,1.72+bob),.08,gray);ball('head',(0,0,1.85+bob),(.15,.14,.21),gray);ball('noseDirectionPlusY',(0,.138,1.85+bob),(.045,.055,.055),black)
 rec={'pose':idx,'phase':phase['phase'],'hipZ':phase['hipZ'],'joints':{}}
 for side,x,m,info in [('LEFT',-.18,near,phase['left']),('RIGHT',.18,far,phase['right'])]:
  footY,ankleZ,contact=info;hip=(x,0,phase['hipZ']);ankle=(x,footY,ankleZ);k=knee(hip,ankle);limb(side+'thigh',hip,k,.105,m);ball(side+'knee',k,(.10,.10,.10),m);limb(side+'shin',k,ankle,.077,m);ball(side+'ankle',ankle,(.07,.07,.08),m)
  footZ=ankleZ-.012;foot=ball(side+'foot',(x,footY+.08,footZ),(.095,.17,.06),m);foot.rotation_euler.x=({'landing':.08,'load':0,'recovery':-.35,'pass':-.18,'air_trailing':-.40,'air_leading':.08}[contact]);armSwing=.09 if footY<0 else -.09;shoulder=(x/abs(x)*.31,0,1.54+bob);elbow=(x/abs(x)*.4,armSwing,1.24+bob);wrist=(x/abs(x)*.43,armSwing*.7,.99+bob);ball(side+'shoulder',shoulder,(.10,.10,.10),m);limb(side+'upperarm',shoulder,elbow,.075,m);limb(side+'forearm',elbow,wrist,.065,m);ball(side+'hand',wrist,(.07,.06,.085),m)
  rec['joints'][side]={'hip':hip,'knee':k,'ankle':ankle,'foot':(x,footY+.08,footZ),'support':contact,'thigh_length':(Vector(k)-Vector(hip)).length,'shin_length':(Vector(ankle)-Vector(k)).length,'minimum_foot_clearance_lower_bound':round(max(0,footZ-.10),3)}
 bpy.ops.object.camera_add(location=(-5,-7,5));cam=bpy.context.object;cam.rotation_euler=(Vector((0,0,1.0))-cam.location).to_track_quat('-Z','Y').to_euler();cam.data.type='ORTHO';cam.data.ortho_scale=3.0;bpy.context.scene.camera=cam
 scene=bpy.context.scene;scene.render.engine='BLENDER_WORKBENCH';scene.display.shading.light='STUDIO';scene.display.shading.studio_light='paint.sl';scene.display.shading.color_type='MATERIAL';scene.display.shading.show_shadows=True;scene.display.shading.show_cavity=True;scene.display.shading.cavity_type='BOTH';scene.display.shading.background_type='WORLD';scene.world.color=(.12,.13,.15);scene.render.resolution_x=1024;scene.render.resolution_y=1024;scene.render.resolution_percentage=100;scene.render.image_settings.file_format='PNG';scene.render.filepath=str(out/f'pose-guide-{idx}.png');bpy.ops.render.render(write_still=True)
 for side in ['LEFT','RIGHT']:
  rec['joints'][side]['projected_native1024']={}
  for joint in ['hip','knee','ankle','foot']:
   v=world_to_camera_view(scene,cam,Vector(rec['joints'][side][joint]));rec['joints'][side]['projected_native1024'][joint]=[round(v.x*1024,2),round((1-v.y)*1024,2)]
 proof.append(rec)
(out/'3d-run-joint-authority.json').write_text(json.dumps({'schema':'pr122-private-3d-run-authoring-guide-v1','camera':[-5,-7,5],'forward_world_axis':'+Y projectsNWupperLEFT','anatomical_RIGHT':'+Xfar/imageRIGHTorange','anatomical_LEFT':'-Xnear/imageLEFTblue','bone_lengths':{'thigh':.57,'shin':.57},'poses':proof,'actor_approval_added':0},indent=2)+'\n')
